// Определяем режим сессии и явный запрос менеджера.
// Состояние храним в workflow static data: sessionId -> "bot" | "manager".
const store = $getWorkflowStaticData('global');
store.modes = store.modes || {};
store.buffers = store.buffers || {};

const item = $input.first().json;
const sessionId = item.sessionId || (item.body && item.body.sessionId) || 'default';
const chatInput = item.chatInput || (item.body && item.body.chatInput) || '';

if (!store.modes[sessionId]) store.modes[sessionId] = 'bot';
let mode = store.modes[sessionId];

// Явная просьба перевести на живого человека.
const text = String(chatInput).toLowerCase();
const patterns = [
  'менеджер', 'менеджера', 'менеджеру',
  'оператор', 'оператора',
  'живой', 'живого', 'человек', 'человека',
  'позови', 'позовите',
  'соедини', 'соедините',
  'переключи', 'переключите',
  'поговорить с'
];
const handoff = mode !== 'manager' && patterns.some((p) => text.includes(p));
if (handoff) {
  mode = 'manager';
  store.modes[sessionId] = 'manager';
}

// Последняя сессия, которую ведёт менеджер: запасной способ, если менеджер
// ответит в Telegram без Reply (без reply_to_message).
if (mode === 'manager') {
  store.lastManagerSession = sessionId;
}

return [{ json: { sessionId, chatInput, mode, handoff } }];

// Ответ менеджера из Telegram -> буфер для клиента.
// Сессию берём из [session:...] в процитированном сообщении (Reply).
const store = $getWorkflowStaticData('global');
store.buffers = store.buffers || {};

const item = $input.first().json;
const msg = item.message || {};
const text = msg.text || '';
const quoted = (msg.reply_to_message && msg.reply_to_message.text) || '';

// Мягкий разбор: подходит и [session:ID], и session:ID.
const findSession = (s) => {
  const m = String(s || '').match(/session:\s*([^\s\]]+)/);
  return m ? m[1].trim() : null;
};
const sessionId = findSession(quoted) || findSession(text) || store.lastManagerSession || null;

if (sessionId && text) {
  store.buffers[sessionId] = store.buffers[sessionId] || [];
  store.buffers[sessionId].push({ text, ts: Date.now() });
}

return [{ json: { sessionId, text, delivered: Boolean(sessionId && text) } }];

// Поллинг с сайта: отдаём накопленные сообщения менеджера и очищаем буфер.
const store = $getWorkflowStaticData('global');
store.buffers = store.buffers || {};

const item = $input.first().json;
const sessionId = (item.query && item.query.sessionId) || 'default';
const buffer = store.buffers[sessionId] || [];
store.buffers[sessionId] = [];

return [{ json: { sessionId, count: buffer.length, messages: buffer.map((x) => x.text) } }];
